// Shape of public/assets/field-layout.json (generated by tools/convert-field.mjs from the field CAD).
// Units: meters, Y up, origin at field center on the tile surface. Red alliance at -X, audience at +Z.

export type Vec3 = [number, number, number];

export interface FieldLayout {
  pollen: Vec3[];
  nectar: { red: Vec3[]; blue: Vec3[] };
  flowers: { name: string; center: [number, number]; topY: number; min: Vec3; max: Vec3 }[];
  hives: Record<'red' | 'blue', { pivot: Vec3; min: Vec3; max: Vec3 }>;
  tape: { color: 'red' | 'blue'; min: Vec3; max: Vec3 }[];
  /** Distance from field center to the inner face of the perimeter walls */
  wallInnerHalf: number;
}

export const TILE_SIZE = 24 * 0.0254;
// Diameters from the official game element CAD (Field/am-5851, am-5852).
export const POLLEN_RADIUS = 0.0711 / 2;
export const NECTAR_RADIUS = 0.0919 / 2;
